function chooseAssignment(q,uid){const input=q.document.querySelector('#dialog-form [name=advisorUid][value="'+uid+'"]');assert.ok(input,'approved candidate '+uid);for(const radio of q.document.querySelectorAll('#dialog-form [name=advisorUid]')){radio.checked=radio===input;radio.toggleAttribute('checked',radio===input);}input.dispatchEvent(new q.window.Event('change',{bubbles:true}));return input;}

function clickLabel(q,label,scope='#view-content'){const button=[...q.document.querySelectorAll(scope+' button')].find(item=>item.textContent===label);assert.ok(button,'button '+label);button.click();return button;}
function dispatchForm(q,form=q.document.querySelector('#dialog-form')){form.dispatchEvent(new q.window.Event('submit',{cancelable:true}));return form;}
function confirmOrientation(q,checked=true){const field=q.document.querySelector('#dialog-form [name=confirmOrientation]');assert.ok(field);field.checked=checked;return field;}
function emitGroup(q,id,data={}){const callback=q.mock.groupCallbacks?.get(id);assert.ok(callback,'listener '+id);callback({tasks:[],events:[],messages:[],...data});q.route('group',id);}
function noticeRecord(patch={}){return {id:'orientation-1',groupId:'assign-g',groupName:'Grupo sem orientador',type:'assigned',newAdvisorName:'Ângelo Silva',createdAt:1793880900000,read:false,...patch};}

const proposalText=(patch={})=>({mode:'text',version:'proposal-v1',topics:{problem:'Problema da escola',objective:'Propor uma melhoria',method:'Pesquisa e testes',expectedResult:'Protótipo funcional'},...patch});
const proposalAttachment=(patch={})=>({mode:'file',version:'proposal-v1',filename:'proposta-assinada.pdf',size:2048,contentType:'application/pdf',...patch});
const proposalInvite=(patch={})=>({id:'proposal-i',groupId:'proposal-g',groupName:'Pesquisa da Joana',type:'advisor',status:'pending',toUid:'prof-1',senderId:'student-a',...patch});
const proposalInvitationData=(patch={})=>({profile:{name:'Ângelo Silva',requestedRole:'advisor'},role:'advisor',groups:[],advisors:advisorFixtures,users:[],invitations:[proposalInvite()],...patch});
function invitedProfessor(patch={}){const q=make();q.ui.sessionChanged({uid:'prof-1',email:'prof-1@example.invalid',displayName:'Ângelo Silva',emailVerified:true});q.mock.appCallback(proposalInvitationData(patch));q.route('invitations');return q;}

