 await test('people pagination traverses every record once and respects its first and last boundaries',async()=>{
  const q=await paginatedManagement(),expected=paginatedPeople().map(person=>person.id),seen=[];
  for(let page=1;page<=9;page++){
   const ids=managedPageIds(q);assert.deepEqual(ids,expected.slice((page-1)*10,page*10));seen.push(...ids);
   assert.equal(q.document.querySelector('#admin-user-page').textContent,'Página '+page+' de 9');
   if(page<9)moveManagedPage(q,'next');
  }
  assert.deepEqual(seen,expected);assert.equal(new Set(seen).size,83);
  assert.equal(q.document.querySelector('#admin-user-range').textContent,'Mostrando 81–83 de 83 cadastros');
  assert.equal(q.document.querySelector('#admin-users-next').disabled,true);
  moveManagedPage(q,'prev');assert.deepEqual(managedPageIds(q),expected.slice(70,80));
  for(let page=8;page>1;page--)moveManagedPage(q,'prev');
  assert.equal(q.document.querySelector('#admin-users-prev').disabled,true);assert.deepEqual(managedPageIds(q),expected.slice(0,10));q.close();
 });
